css:
.slop-min-hero { padding: 5.5rem 1.5rem 4.5rem; text-align: center; box-sizing: border-box; }
.slop-min-hero__inner { max-width: 760px; margin: 0 auto; }
.slop-min-hero__title { margin: 0 0 1.25rem; font-family: var(--slop-font-heading); font-size: clamp(2rem, 4.2vw, 3.25rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.02em; color: var(--slop-fg); }
.slop-min-hero__subhead { margin: 0 auto 2rem; max-width: 600px; font-family: var(--slop-font-body); font-size: 1.125rem; line-height: 1.65; color: var(--slop-muted); }
.slop-min-hero__actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 0.75rem; }
.slop-min-hero__cta { display: inline-flex; align-items: center; justify-content: center; padding: 0.85rem 1.75rem; border-radius: 0.5rem; background: var(--slop-accent1); color: #ffffff; font-family: var(--slop-font-body); font-weight: 600; font-size: 1rem; text-decoration: none; transition: opacity 0.2s ease; }
.slop-min-hero__cta:hover { opacity: 0.92; }

.slop-clean-feat { padding: 3.5rem 1.5rem; box-sizing: border-box; }
.slop-clean-feat__inner { max-width: 1120px; margin: 0 auto; }
.slop-clean-feat__heading { margin: 0 0 2rem; text-align: center; font-family: var(--slop-font-heading); font-size: clamp(1.5rem, 2.8vw, 2.125rem); font-weight: 700; color: var(--slop-fg); }
.slop-clean-feat__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1.5rem; }
.slop-clean-feat__card { padding: 1.75rem; border-radius: 0.75rem; background: var(--slop-surface); border: 1px solid var(--slop-border); text-align: left; box-sizing: border-box; }
.slop-clean-feat__index { display: inline-block; margin-bottom: 0.75rem; font-family: var(--slop-font-body); font-size: 0.8125rem; font-weight: 600; color: var(--slop-accent1); letter-spacing: 0.06em; }
.slop-clean-feat__title { margin: 0 0 0.65rem; font-family: var(--slop-font-heading); font-size: 1.125rem; font-weight: 600; color: var(--slop-fg); }
.slop-clean-feat__body { margin: 0; font-family: var(--slop-font-body); font-size: 0.95rem; line-height: 1.6; color: var(--slop-muted); }

.slop-simple-cta { padding: 3.5rem 1.5rem 4.5rem; box-sizing: border-box; }
.slop-simple-cta__box { max-width: 900px; margin: 0 auto; padding: 2.75rem 2rem; border-radius: 0.875rem; background: var(--slop-surface); border: 1px solid var(--slop-border); text-align: center; box-sizing: border-box; }
.slop-simple-cta__title { margin: 0 0 0.75rem; font-family: var(--slop-font-heading); font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 700; color: var(--slop-fg); }
.slop-simple-cta__text { margin: 0 auto 1.75rem; max-width: 540px; font-family: var(--slop-font-body); font-size: 1rem; line-height: 1.6; color: var(--slop-muted); }
.slop-simple-cta__btn { display: inline-flex; align-items: center; justify-content: center; padding: 0.85rem 1.75rem; border-radius: 0.5rem; background: var(--slop-accent1); color: #ffffff; font-family: var(--slop-font-body); font-weight: 600; font-size: 0.975rem; text-decoration: none; transition: opacity 0.2s ease; }
.slop-simple-cta__btn:hover { opacity: 0.92; }

.slop-dual-hero { padding: 6rem 1.5rem 4.75rem; text-align: center; box-sizing: border-box; }
.slop-dual-hero__inner { max-width: 820px; margin: 0 auto; }
.slop-dual-hero__eyebrow { margin: 0 0 0.85rem; font-family: var(--slop-font-body); font-size: 0.875rem; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: var(--slop-accent1); }
.slop-dual-hero__title { margin: 0 0 1.25rem; font-family: var(--slop-font-heading); font-size: clamp(2.25rem, 5vw, 3.75rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.03em; color: var(--slop-fg); }
.slop-dual-hero__subhead { margin: 0 auto 2.25rem; max-width: 640px; font-family: var(--slop-font-body); font-size: 1.125rem; line-height: 1.65; color: var(--slop-muted); }
.slop-dual-hero__actions { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 1rem; }
.slop-dual-hero__primary { display: inline-flex; align-items: center; justify-content: center; padding: 0.9rem 1.9rem; border-radius: 0.65rem; background: var(--slop-gradient); color: #ffffff; font-family: var(--slop-font-body); font-weight: 600; font-size: 1rem; text-decoration: none; box-shadow: 0 10px 24px var(--slop-glow); transition: transform 0.2s ease, opacity 0.2s ease; }
.slop-dual-hero__primary:hover { transform: translateY(-2px); opacity: 0.96; }
.slop-dual-hero__secondary { display: inline-flex; align-items: center; justify-content: center; padding: 0.9rem 1.9rem; border-radius: 0.65rem; background: var(--slop-surface); color: var(--slop-fg); border: 1px solid var(--slop-border); font-family: var(--slop-font-body); font-weight: 600; font-size: 1rem; text-decoration: none; box-shadow: 0 4px 14px rgba(15, 23, 42, 0.06); transition: transform 0.2s ease, border-color 0.2s ease; }
.slop-dual-hero__secondary:hover { transform: translateY(-2px); border-color: var(--slop-accent1); }

.slop-newsletter { padding: 3.5rem 1.5rem; box-sizing: border-box; }
.slop-newsletter__card { max-width: 780px; margin: 0 auto; padding: 2.75rem 2rem; border-radius: 1.25rem; background: var(--slop-surface); border: 1px solid var(--slop-border); text-align: center; box-shadow: 0 12px 32px rgba(15, 23, 42, 0.12); box-sizing: border-box; }
.slop-newsletter__title { margin: 0 0 0.75rem; font-family: var(--slop-font-heading); font-size: clamp(1.5rem, 3vw, 2.125rem); font-weight: 700; color: var(--slop-fg); }
.slop-newsletter__desc { margin: 0 auto 1.75rem; max-width: 540px; font-family: var(--slop-font-body); font-size: 1rem; line-height: 1.6; color: var(--slop-muted); }
.slop-newsletter__form { display: flex; justify-content: center; align-items: stretch; flex-wrap: wrap; gap: 0.75rem; max-width: 540px; margin: 0 auto; }
.slop-newsletter__sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); border: 0; }
.slop-newsletter__input { flex: 1 1 240px; min-width: 0; padding: 0.9rem 1.15rem; border-radius: 0.75rem; border: 1px solid var(--slop-border); background: var(--slop-bg); color: var(--slop-fg); font-family: var(--slop-font-body); font-size: 0.975rem; outline: none; box-sizing: border-box; }
.slop-newsletter__input:focus { border-color: var(--slop-accent1); box-shadow: 0 0 0 3px var(--slop-glow); }
.slop-newsletter__submit { flex: 0 0 auto; padding: 0.9rem 1.75rem; border: 0; border-radius: 0.75rem; background: var(--slop-gradient); color: #ffffff; font-family: var(--slop-font-body); font-weight: 600; font-size: 0.975rem; cursor: pointer; box-shadow: 0 0 22px var(--slop-glow); transition: transform 0.2s ease, box-shadow 0.2s ease; }
.slop-newsletter__submit:hover { transform: translateY(-2px); box-shadow: 0 0 30px var(--slop-glow); }

.slop-grad-hero { position: relative; padding: 6.5rem 1.5rem 5rem; text-align: center; box-sizing: border-box; }
.slop-grad-hero__inner { max-width: 920px; margin: 0 auto; }
.slop-grad-hero__badge { display: inline-flex; align-items: center; gap: 0.5rem; margin-bottom: 1.75rem; padding: 0.45rem 1.15rem; border-radius: 9999px; background: var(--slop-surface); border: 1px solid var(--slop-border); color: var(--slop-fg); font-family: var(--slop-font-body); font-size: 0.875rem; font-weight: 600; box-shadow: 0 0 24px var(--slop-glow); }
.slop-grad-hero__title { margin: 0 0 1.5rem; font-family: var(--slop-font-heading); font-size: clamp(2.75rem, 6vw, 4.75rem); font-weight: 800; line-height: 1.06; letter-spacing: -0.04em; background: linear-gradient(135deg, #ffffff 0%, var(--slop-accent1) 50%, var(--slop-accent2) 100%); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.slop-grad-hero__subhead { margin: 0 auto 2.5rem; max-width: 680px; font-family: var(--slop-font-body); font-size: clamp(1.05rem, 2vw, 1.25rem); line-height: 1.65; color: var(--slop-muted); }
.slop-grad-hero__actions { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 1rem; }
.slop-grad-hero__primary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2.15rem; border-radius: 0.85rem; background: var(--slop-gradient); color: #ffffff; font-family: var(--slop-font-body); font-weight: 700; font-size: 1.025rem; text-decoration: none; box-shadow: 0 0 28px var(--slop-glow); transition: transform 0.25s ease, box-shadow 0.25s ease; }
.slop-grad-hero__primary:hover { transform: translateY(-3px) scale(1.03); box-shadow: 0 0 40px var(--slop-glow); }
.slop-grad-hero__secondary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2.15rem; border-radius: 0.85rem; background: rgba(255, 255, 255, 0.06); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); color: var(--slop-fg); border: 1px solid var(--slop-border); font-family: var(--slop-font-body); font-weight: 600; font-size: 1.025rem; text-decoration: none; transition: transform 0.25s ease, border-color 0.25s ease; }
.slop-grad-hero__secondary:hover { transform: translateY(-3px); border-color: var(--slop-accent1); }

.slop-emoji-feat { padding: 4rem 1.5rem; box-sizing: border-box; }
.slop-emoji-feat__inner { max-width: 1120px; margin: 0 auto; text-align: center; }
.slop-emoji-feat__heading { margin: 0 0 0.75rem; font-family: var(--slop-font-heading); font-size: clamp(1.75rem, 3.5vw, 2.5rem); font-weight: 800; letter-spacing: -0.025em; color: var(--slop-fg); }
.slop-emoji-feat__lead { margin: 0 auto 2.5rem; max-width: 600px; font-family: var(--slop-font-body); font-size: 1.05rem; color: var(--slop-muted); }
.slop-emoji-feat__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1.5rem; }
.slop-emoji-feat__card { padding: 2rem; border-radius: 1.15rem; background: var(--slop-surface); border: 1px solid var(--slop-border); text-align: left; transition: transform 0.28s ease, box-shadow 0.28s ease, border-color 0.28s ease; box-sizing: border-box; }
.slop-emoji-feat__card:hover { transform: translateY(-6px); border-color: var(--slop-accent1); box-shadow: 0 18px 36px var(--slop-glow); }
.slop-emoji-feat__icon { width: 3.25rem; height: 3.25rem; display: inline-flex; align-items: center; justify-content: center; margin-bottom: 1.25rem; border-radius: 0.85rem; background: var(--slop-gradient); font-size: 1.5rem; box-shadow: 0 8px 20px var(--slop-glow); }
.slop-emoji-feat__title { margin: 0 0 0.65rem; font-family: var(--slop-font-heading); font-size: 1.2rem; font-weight: 700; color: var(--slop-fg); }
.slop-emoji-feat__body { margin: 0; font-family: var(--slop-font-body); font-size: 0.96rem; line-height: 1.6; color: var(--slop-muted); }

.slop-glass-feat { padding: 4rem 1.5rem; box-sizing: border-box; }
.slop-glass-feat__inner { max-width: 1120px; margin: 0 auto; }
.slop-glass-feat__heading { margin: 0 0 2.25rem; text-align: center; font-family: var(--slop-font-heading); font-size: clamp(1.75rem, 3.2vw, 2.35rem); font-weight: 800; color: var(--slop-fg); }
.slop-glass-feat__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1.5rem; }
.slop-glass-feat__card { padding: 2rem; border-radius: 1.25rem; background: rgba(255, 255, 255, 0.06); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border: 1px solid var(--slop-border); box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 16px 36px rgba(0, 0, 0, 0.22); transition: transform 0.3s ease, border-color 0.3s ease; box-sizing: border-box; }
.slop-glass-feat__card:hover { transform: translateY(-5px); border-color: var(--slop-accent1); }
.slop-glass-feat__badge { display: inline-flex; align-items: center; gap: 0.35rem; margin-bottom: 1rem; padding: 0.35rem 0.75rem; border-radius: 9999px; background: rgba(139, 92, 246, 0.16); border: 1px solid var(--slop-border); font-family: var(--slop-font-body); font-size: 0.8rem; font-weight: 600; color: var(--slop-fg); }
.slop-glass-feat__title { margin: 0 0 0.65rem; font-family: var(--slop-font-heading); font-size: 1.2rem; font-weight: 700; color: var(--slop-fg); }
.slop-glass-feat__body { margin: 0; font-family: var(--slop-font-body); font-size: 0.96rem; line-height: 1.65; color: var(--slop-muted); }

.slop-stats { padding: 3.5rem 1.5rem; box-sizing: border-box; }
.slop-stats__inner { max-width: 1120px; margin: 0 auto; padding: 2.25rem 1.75rem; border-radius: 1.25rem; background: var(--slop-surface); border: 1px solid var(--slop-border); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); box-sizing: border-box; }
.slop-stats__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(200px, 100%), 1fr)); gap: 1.5rem; text-align: center; }
.slop-stats__item { display: flex; flex-direction: column; align-items: center; gap: 0.4rem; padding: 0.5rem; }
.slop-stats__value { font-family: var(--slop-font-heading); font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; line-height: 1.05; letter-spacing: -0.03em; background: var(--slop-gradient); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.slop-stats__label { font-family: var(--slop-font-body); font-size: 0.925rem; font-weight: 500; color: var(--slop-muted); }

.slop-testimonials { padding: 4rem 1.5rem; box-sizing: border-box; }
.slop-testimonials__inner { max-width: 1120px; margin: 0 auto; }
.slop-testimonials__heading { margin: 0 0 2.5rem; text-align: center; font-family: var(--slop-font-heading); font-size: clamp(1.75rem, 3.2vw, 2.35rem); font-weight: 800; color: var(--slop-fg); }
.slop-testimonials__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1.5rem; }
.slop-testimonials__card { margin: 0; padding: 2rem; border-radius: 1.15rem; background: var(--slop-surface); border: 1px solid var(--slop-border); display: flex; flex-direction: column; justify-content: space-between; gap: 1.25rem; box-sizing: border-box; }
.slop-testimonials__stars { font-size: 1.15rem; letter-spacing: 0.14em; color: #facc15; }
.slop-testimonials__quote { margin: 0; font-family: var(--slop-font-body); font-size: 0.98rem; line-height: 1.65; color: var(--slop-fg); }
.slop-testimonials__meta { display: flex; flex-direction: column; gap: 0.2rem; }
.slop-testimonials__author { font-family: var(--slop-font-heading); font-size: 1rem; font-weight: 700; color: var(--slop-fg); }
.slop-testimonials__role { font-family: var(--slop-font-body); font-size: 0.875rem; color: var(--slop-muted); }

.slop-blobs { position: fixed; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; }
.slop-blobs__orb { position: absolute; border-radius: 9999px; filter: blur(90px); opacity: 0.42; pointer-events: none; }
.slop-blobs__orb--one { width: 460px; height: 460px; top: -120px; left: -110px; background: radial-gradient(circle, var(--slop-accent1) 0%, transparent 70%); }
.slop-blobs__orb--two { width: 520px; height: 520px; top: 28%; right: -150px; background: radial-gradient(circle, var(--slop-accent2) 0%, transparent 70%); }
.slop-blobs__orb--three { width: 420px; height: 420px; bottom: -140px; left: 32%; background: radial-gradient(circle, var(--slop-accent1) 0%, var(--slop-accent2) 45%, transparent 72%); }

.slop-decor { position: fixed; inset: 0; z-index: -1; overflow: hidden; pointer-events: none; }
.slop-decor__grid { position: absolute; inset: 0; background-image: radial-gradient(rgba(255, 255, 255, 0.14) 1px, transparent 1px); background-size: 28px 28px; opacity: 0.28; }
.slop-decor__sparkle { position: absolute; font-size: 1.35rem; color: var(--slop-accent1); text-shadow: 0 0 18px var(--slop-glow); opacity: 0.75; }
.slop-decor__sparkle--1 { top: 14%; left: 10%; }
.slop-decor__sparkle--2 { top: 24%; right: 12%; font-size: 1.5rem; }
.slop-decor__sparkle--3 { bottom: 20%; left: 16%; color: var(--slop-accent2); }
.slop-decor__orb { position: absolute; border-radius: 9999px; background: var(--slop-gradient); box-shadow: 0 0 24px var(--slop-glow); opacity: 0.55; }
.slop-decor__orb--1 { width: 14px; height: 14px; top: 38%; left: 6%; }
.slop-decor__orb--2 { width: 18px; height: 18px; bottom: 26%; right: 9%; }

.slop-neon-cta { padding: 4rem 1.5rem 5rem; box-sizing: border-box; }
.slop-neon-cta__frame { max-width: 980px; margin: 0 auto; padding: 2px; border-radius: 1.5rem; background: var(--slop-gradient); box-shadow: 0 0 36px var(--slop-glow); box-sizing: border-box; }
.slop-neon-cta__inner { padding: 3.5rem 2rem; border-radius: calc(1.5rem - 2px); background: var(--slop-bg); text-align: center; box-sizing: border-box; }
.slop-neon-cta__title { margin: 0 0 1rem; font-family: var(--slop-font-heading); font-size: clamp(1.85rem, 3.8vw, 2.75rem); font-weight: 800; letter-spacing: -0.03em; background: var(--slop-gradient); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
.slop-neon-cta__subhead { margin: 0 auto 2.25rem; max-width: 620px; font-family: var(--slop-font-body); font-size: 1.075rem; line-height: 1.65; color: var(--slop-muted); }
.slop-neon-cta__actions { display: flex; justify-content: center; align-items: center; flex-wrap: wrap; gap: 1rem; }
.slop-neon-cta__primary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2.25rem; border-radius: 0.85rem; background: var(--slop-gradient); color: #ffffff; font-family: var(--slop-font-body); font-weight: 700; font-size: 1.025rem; text-decoration: none; box-shadow: 0 0 28px var(--slop-glow); transition: transform 0.25s ease, box-shadow 0.25s ease; }
.slop-neon-cta__primary:hover { transform: scale(1.05); box-shadow: 0 0 42px var(--slop-glow); }
.slop-neon-cta__secondary { display: inline-flex; align-items: center; justify-content: center; padding: 1rem 2rem; border-radius: 0.85rem; background: var(--slop-surface); border: 1px solid var(--slop-border); color: var(--slop-fg); font-family: var(--slop-font-body); font-weight: 600; font-size: 1rem; text-decoration: none; transition: transform 0.25s ease, border-color 0.25s ease; }
.slop-neon-cta__secondary:hover { transform: scale(1.05); border-color: var(--slop-accent1); }

.slop-heavy-feat { padding: 4rem 1.5rem; box-sizing: border-box; }
.slop-heavy-feat__inner { max-width: 1120px; margin: 0 auto; }
.slop-heavy-feat__heading { margin: 0 0 2.5rem; text-align: center; font-family: var(--slop-font-heading); font-size: clamp(1.75rem, 3.2vw, 2.4rem); font-weight: 800; color: var(--slop-fg); }
.slop-heavy-feat__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(260px, 100%), 1fr)); gap: 1.75rem; }
.slop-heavy-feat__card { padding: 2.15rem; border-radius: 1.35rem; background: var(--slop-surface); border: 1px solid var(--slop-border); box-shadow: 0 24px 48px rgba(0, 0, 0, 0.45), 0 0 28px var(--slop-glow), inset 0 1px 0 rgba(255, 255, 255, 0.16); transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease; box-sizing: border-box; }
.slop-heavy-feat__card:hover { transform: scale(1.05) translateY(-4px); border-color: var(--slop-accent1); box-shadow: 0 30px 60px rgba(0, 0, 0, 0.55), 0 0 42px var(--slop-glow), inset 0 1px 0 rgba(255, 255, 255, 0.24); }
.slop-heavy-feat__pill { display: inline-flex; align-items: center; gap: 0.35rem; margin-bottom: 1.1rem; padding: 0.35rem 0.85rem; border-radius: 9999px; background: var(--slop-gradient); color: #ffffff; font-family: var(--slop-font-body); font-size: 0.8rem; font-weight: 700; box-shadow: 0 0 18px var(--slop-glow); }
.slop-heavy-feat__title { margin: 0 0 0.7rem; font-family: var(--slop-font-heading); font-size: 1.25rem; font-weight: 700; color: var(--slop-fg); }
.slop-heavy-feat__body { margin: 0; font-family: var(--slop-font-body); font-size: 0.96rem; line-height: 1.65; color: var(--slop-muted); }
